def max_product(nums):
    # Initialize an array to store the maximum product subsequence at each index
    mp = [0 for x in range(len(nums))]
    mp[0] = nums[0]  # The maximum product subsequence at the first index is the element itself

    # Iterate through the array starting from the second element
    for i in range(1, len(nums)):
        # Check all previous elements to find the maximum product subsequence that can be extended by nums[i]
        for j in range(i):
            if nums[i] > nums[j] and mp[i] < mp[j] * nums[i]:
                mp[i] = mp[j] * nums[i]
        # If no increasing subsequence found, the element itself is the maximum product subsequence
        if mp[i] == 0:
            mp[i] = nums[i]

    # Return the maximum value from the mp array, which represents the maximum product subsequence
    return max(mp)
