def jacobsthal_num(n): 
    if n == 0: 
        return 0
    if n == 1: 
        return 1
    i, j, k = 0, 1, 0
    for c in range(2, n + 1): 
        k = i + 2 * j 
        i = j 
        j = k 
    return k
